# naive_answer.py — answers only from frozen training data
TRAINING_SNAPSHOT = {
    "sick_leave_days_per_year": 10,   # what it saw at training time
}

def answer(question: str) -> str:
    if "sick" in question.lower():
        days = TRAINING_SNAPSHOT["sick_leave_days_per_year"]
        return f"You get {days} sick days this year."
    return "I don't know."

# no retrieval step — this is the whole memory it has

# rag_answer.py — retrieve the current passage, THEN answer
DOCUMENT_STORE = {
    "sick_leave_policy": (
        "Effective this year, employees receive 15 sick days "
        "annually (updated 8 months ago, replacing the previous "
        "10-day allowance)."
    ),
}

def retrieve(question: str) -> str:      # <- the new step
    if "sick" in question.lower():
        return DOCUMENT_STORE["sick_leave_policy"]
    return ""

def answer(question: str) -> str:
    passage = retrieve(question)          # conditioned on this
    return f"Based on the current policy: {passage}"
